#!/bin/bash
# Uninstall script for Monotype Desktop App
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Monotype Desktop App..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Monotype Desktop App if running..."
pkill -f "Monotype Desktop App" 2>/dev/null || true

# Unload service com.monotype.mfep
echo "Unloading service com.monotype.mfep..."
launchctl unload -w /Library/LaunchAgents/com.monotype.mfep.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.monotype.mfep.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.monotype.mfep.plist 2>/dev/null || true

# Unload service com.monotype.monitorService
echo "Unloading service com.monotype.monitorService..."
launchctl unload -w /Library/LaunchAgents/com.monotype.monitorService.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.monotype.monitorService.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.monotype.monitorService.plist 2>/dev/null || true

# Unload service com.monotype.ms
echo "Unloading service com.monotype.ms..."
launchctl unload -w /Library/LaunchAgents/com.monotype.ms.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.monotype.ms.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.monotype.ms.plist 2>/dev/null || true

# Unload service com.monotype.updater
echo "Unloading service com.monotype.updater..."
launchctl unload -w /Library/LaunchAgents/com.monotype.updater.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.monotype.updater.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.monotype.updater.plist 2>/dev/null || true

# Kill application with bundle ID com.monotype.monotype-fonts if running
echo "Stopping application with bundle ID com.monotype.monotype-fonts if running..."
killall -9 "com.monotype.monotype-fonts" 2>/dev/null || true

# Remove $HOME/Library/Application Scripts/com.monotype.notification-service
echo "Removing $HOME/Library/Application Scripts/com.monotype.notification-service..."
if [ -d "$HOME/Library/Application Scripts/com.monotype.notification-service" ]; then
    rm -rf "$HOME/Library/Application Scripts/com.monotype.notification-service" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Scripts/com.monotype.notification-service" ]; then
    rm -f "$HOME/Library/Application Scripts/com.monotype.notification-service" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.monotype.*.sfl*
echo "Removing $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.monotype.*.sfl*..."
if [ -d "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.monotype.*.sfl*" ]; then
    rm -rf "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.monotype.*.sfl*" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.monotype.*.sfl*" ]; then
    rm -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.monotype.*.sfl*" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Monotype Fonts
echo "Removing $HOME/Library/Application Support/Monotype Fonts..."
if [ -d "$HOME/Library/Application Support/Monotype Fonts" ]; then
    rm -rf "$HOME/Library/Application Support/Monotype Fonts" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Monotype Fonts" ]; then
    rm -f "$HOME/Library/Application Support/Monotype Fonts" 2>/dev/null || true
fi

# Remove $HOME/Library/Containers/com.monotype.notification-service
echo "Removing $HOME/Library/Containers/com.monotype.notification-service..."
if [ -d "$HOME/Library/Containers/com.monotype.notification-service" ]; then
    rm -rf "$HOME/Library/Containers/com.monotype.notification-service" 2>/dev/null || true
elif [ -f "$HOME/Library/Containers/com.monotype.notification-service" ]; then
    rm -f "$HOME/Library/Containers/com.monotype.notification-service" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/Monotype Fonts
echo "Removing $HOME/Library/Logs/Monotype Fonts..."
if [ -d "$HOME/Library/Logs/Monotype Fonts" ]; then
    rm -rf "$HOME/Library/Logs/Monotype Fonts" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/Monotype Fonts" ]; then
    rm -f "$HOME/Library/Logs/Monotype Fonts" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.monotype.*.plist
echo "Removing $HOME/Library/Preferences/com.monotype.*.plist..."
if [ -d "$HOME/Library/Preferences/com.monotype.*.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.monotype.*.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.monotype.*.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.monotype.*.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.monotype.*.savedState
echo "Removing $HOME/Library/Saved Application State/com.monotype.*.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.monotype.*.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.monotype.*.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.monotype.*.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.monotype.*.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
